usage:
import { VoiceNote } from "./VoiceNote";
import "./VoiceNote.css";

<VoiceNote
  bars={28}
  gain={60}
  bounce={40}
  corner={28}
/>

notes:
/* THE PLAYHEAD IS ONE VARIABLE. Each bar lights itself
   once progress has passed its index — no render per frame. */
.bar { opacity: clamp(.3, calc((var(--prog) * var(--n) - var(--i)) * 99), 1); }

/* slide left to throw it away */
pull = clamp((x0 - x) / 90, 0, 1);
if (pull >= 1) cancel();

/* the pill opens on a curve whose y1 past 1 is the bounce */
.pill { transition: width 460ms cubic-bezier(.3, var(--ov), .4, 1); }
